diff --git a/src/factura.mjs b/src/factura.mjs
index 5d01137..5e99f58 100644
--- a/src/factura.mjs
+++ b/src/factura.mjs
@@ -8,17 +8,24 @@ export function validarNit(nit) {
 }

 // RF-002: el IVA va incluido en el precio; se informa, no se suma.
-export function calcularFactura(items) {
+// RF-006: `descuentoGlobal` (porcentaje 0-100) se aplica sobre la suma de líneas, antes del IVA.
+export function calcularFactura(items, { descuentoGlobal } = {}) {
   if (!Array.isArray(items) || items.length === 0) throw new Error("Una factura necesita al menos una línea");
-  let totalCentavos = 0;
+  const conDescuento = descuentoGlobal !== undefined;
+  if (conDescuento && (typeof descuentoGlobal !== "number" || !(descuentoGlobal >= 0 && descuentoGlobal <= 100)))
+    throw new RangeError("Descuento inválido: debe estar entre 0 y 100");
+  let subtotalCentavos = 0;
   for (const item of items) {
     if (!Number.isInteger(item.cantidad) || item.cantidad <= 0) throw new RangeError("Cantidad inválida");
     if (!Number.isInteger(item.precioUnitarioCentavos) || item.precioUnitarioCentavos < 0)
       throw new RangeError("Precio inválido: debe estar en centavos enteros");
-    totalCentavos += item.cantidad * item.precioUnitarioCentavos;
+    subtotalCentavos += item.cantidad * item.precioUnitarioCentavos;
   }
+  const descuentoCentavos = conDescuento ? Math.round((subtotalCentavos * descuentoGlobal) / 100) : 0;
+  const totalCentavos = subtotalCentavos - descuentoCentavos;
   const ivaCentavos = Math.round(totalCentavos * TASA_IVA);
-  return { totalCentavos, ivaCentavos, netoCentavos: totalCentavos - ivaCentavos };
+  const factura = { totalCentavos, ivaCentavos, netoCentavos: totalCentavos - ivaCentavos };
+  return conDescuento ? { subtotalCentavos, descuentoCentavos, ...factura } : factura;
 }

 // RF-001, RF-003: emite una factura válida y congelada.
diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..b7f147f 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -22,6 +22,30 @@ test("ADR-001: montos en centavos enteros", () => {
   assert.throws(() => calcularFactura([]));
 });

+test("RF-006: descuento global en porcentaje, antes del IVA", () => {
+  const items = [
+    { cantidad: 2, precioUnitarioCentavos: 5000 },
+    { cantidad: 1, precioUnitarioCentavos: 1050 },
+  ];
+  assert.deepEqual(calcularFactura(items, { descuentoGlobal: 10 }), {
+    subtotalCentavos: 11050,
+    descuentoCentavos: 1105,
+    totalCentavos: 9945,
+    ivaCentavos: 1293,
+    netoCentavos: 8652,
+  });
+  assert.deepEqual(calcularFactura(items, {}), calcularFactura(items));
+  assert.equal(calcularFactura(items, { descuentoGlobal: 0 }).totalCentavos, 11050);
+  assert.equal(calcularFactura(items, { descuentoGlobal: 100 }).totalCentavos, 0);
+});
+
+test("RF-006: descuento global fuera de 0-100 se rechaza", () => {
+  const items = [{ cantidad: 1, precioUnitarioCentavos: 1000 }];
+  for (const d of [-1, 100.5, NaN, "10", null]) {
+    assert.throws(() => calcularFactura(items, { descuentoGlobal: d }), RangeError);
+  }
+});
+
 test("RF-003: una factura emitida no se puede modificar", () => {
   const f = emitirFactura({ numero: 7, nit: "1023456", razonSocial: "Cliente SA", items: [{ cantidad: 1, precioUnitarioCentavos: 1000 }] });
   assert.equal(f.estado, "emitida");
